<?php $title='Kategori';require '_head.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: categories.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO categories(name,image,sort_order) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['image']),0]);header('Location: categories.php');exit;}$rows=$pdo->query('SELECT * FROM categories ORDER BY sort_order,id DESC')->fetchAll();?><h1>Kategori</h1><div class="panel"><form method="post"><input name="name" placeholder="Nama kategori" required><input name="image" placeholder="/uploads/categories/foto.jpg"><button>Simpan</button></form></div><div class="panel"><?php foreach($rows as $r):?><p><?=e($r['name'])?> — <a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></p><?php endforeach;?></div><?php require '_foot.php';?>